mapper.select:
SELECT ubd.id, ubd.user_id, ubd.busi_type as busiType, ubd.channel, ubd.form_user_id, u.mobile, ubd.original_amount, ubd.remarks, salesman_user.username as salesmanName, u.salesmanid as salesmanId, ubd.stream_id, ubd.transaction_amount, ubd.transaction_date, ubd.use_amount, ubd.create_date, ubd.update_date, u.mobile AS mobile, u.agent, u.biaoqian FROM user_balance_detail ubd LEFT JOIN tb_user u ON ubd.user_id = u.id LEFT JOIN sys_user salesman_user ON u.salesmanid = salesman_user.id
AND u.biaoqian LIKE CONCAT('%', #{biaoqian}, '%')
AND u.biaoqian IS NOT NULL AND u.biaoqian != ''
AND (u.biaoqian IS NULL OR u.biaoqian = '')
AND ubd.busi_type = #{busiType}
AND ubd.transaction_date >= #{startTime}
AND ubd.transaction_date <= #{endTime}
AND (ubd.mobile LIKE CONCAT('%', #{mobile}, '%') OR u.mobile LIKE CONCAT('%', #{mobile}, '%'))
AND u.agent = #{agent}
AND u.salesmanid = #{salesmanid}
AND u.agent = #{currentUserId}
AND u.salesmanid = #{currentUserId}
ORDER BY ubd.transaction_date DESC
